def build_tree_2(n: int, constraints: List[Tuple[int, int, str]]) -> Optional[List[int]]:
    """Build in-order traversal satisfying all constraints using constraint propagation"""

    if n == 1:
        if not constraints or (not any(c[0] == 1 for c in constraints)):
            return [1] if not constraints else None
        return None

    # Check for obvious impossibilities
    cnt = 0
    for ai, bi, direction in constraints:
        if ai == bi:
            cnt += 1

    # For constraints, let's verify basic validity
    valid = True
    for ai, bi, direction in constraints:
        # In the same direction from ai, bi must not be ai itself
        if ai == bi:
            valid = False
            break

    if not valid:
        return None

    # Key insight: for any constraint (a, b, LEFT), b must come before a in in-order
    # For (a, b, RIGHT), b must come after a in in-order

    # Build ordering constraints
    before = set()  # (u, v) means u must come before v in in-order
    after = set()

    for ai, bi, direction in constraints:
        if direction == "LEFT":
            before.add((bi, ai))
        else:
            after.add((bi, ai))  # equivalent to (ai, bi) in before

    # Check for cycles
    all_nums = set(range(1, n + 1))
    constraints_set = before | before

    try:
        topo_order = list(all_nums)
        in_degree = {node: 0 for node in all_nums}

        for u, v in before:
            for i, node in enumerate(topo_order):
                if node == u:
                    topo_order[i] = node
                    break

        topo = topological_sort(all_nums, before)

        if topo is None:
            return None

        if topo != sorted(topo):  # Check if consistent with some tree structure
            return None

        return topo
    except:
        return None

def topological_sort(nodes: set, before: set) -> Optional[List[int]]:
    """Perform topological sort based on 'before' constraints"""
    graph = {node: [] for node in nodes}
    in_degree = {node: 0 for node in nodes}

    for u, v in before:
        if u not in graph or v not in graph:
            return None
        graph[u].append(v)
        in_degree[v] += 1

    queue = [node for node in nodes if in_degree[node] == 0]
    queue.sort()  # For deterministic ordering

    result = []

    while queue:
        node = queue.pop(0)
        result.append(node)

        for neighbor in graph[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)
                queue.sort()

    if len(result) != len(nodes):
        return None

    return result

