    lines = input_str.strip().split('\n')
    if not lines:
        return ""

    n, m = map(int, lines[0].split())
    grid = [list(line) for line in lines[1:n+1]]

    # Find all current connected components of free squares
    parent = {}
    root = []

    def find(x):
        if x not in parent:
            parent[x] = x
            if x not in root:
                root.append(x)
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        px, py = find(x), find(y)
        if px != py:
            parent[px] = py

    # Free cell -> index mapping
    cells = {}
    cell_list = []

    for r in range(n):
        for c in range(m):
            if grid[r][c] == '.':
                idx = (r, c)
                cells[idx] = len(cell_list)
                cell_list.append(idx)

    # Union all connected free squares
    for idx, (r, c) in enumerate(cell_list):
        if r > 0 and (r-1, c) in cells:
            union(idx, cells[(r-1, c)])
        if c > 0 and (r, c-1) in cells:
            union(idx, cells[(r, c-1)])

    # Group cells by their component (represented by root)
    components = {}
    for idx, cell in enumerate(cell_list):
        rpy = find(idx)
        if rpy not in components:
            components[rpy] = []
        components[rpy].append(cell)

    # Build parent map for rectangle checking
    for rpy, cell_list in components.items():
        # All cells in a component should form a rectangle
        # If they don't, we need to remove some walls
        # Find bounding box
        if not cell_list:
            continue

        rs = [c[0] for c in cell_list]
        re = [c[0] for c in cell_list]
        cs = [c[1] for c in cell_list]
        ce = [c[1] for c in cell_list]

        for i, i_c in enumerate(cell_list):
            if not ((i_c[0] in rs or i_c[1] in cs)):
                pass

            # This component needs to become a rectangle
            # The rectangle should span from min_r to max_r and min_c to max_c
            for r in range(rs[0], re[0]+1):
                for c in range(cs[0], ce[0]+1):
                    if (r, c) not in cells:
                        # This should be a wall that we can remove
                        # But we only remove it if it helps forming rectangles
                        pass

    # We need to solve this greedily: 
    # Keep the structure of components and only add free squares 
    # (remove walls) to make each component a rectangle

    # Strategy: For each component, expand it to its bounding box
    # and fill in missing squares by removing walls

    result = [row[:] for row in grid]

    for rpy, cell_list in components.items():
        if not cell_list:
            continue

        # Bounding box
        min_r, max_r = float('inf'), float('-inf')
        min_c, max_c = float('inf'), float('-inf')

        for r, c in cell_list:
            min_r = min(min_r, r)
            max_r = max(max_r, r)
            min_c = min(min_c, c)
            max_c = max(max_c, c)

        # Fill the bounding box
        for r in range(min_r, max_r + 1):
            for c in range(min_c, max_c + 1):
                if (r, c) not in cells:
                    result[r][c] = '.'

    return '\n'.join(''.join(row) for row in result)

