from functools import lru_cache

def solution(s):
    lines = s.strip().split('\n')
    n, u, r = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    b = list(map(int, lines[2].split()))
    k = list(map(int, lines[3].split()))
    p = list(map(int, lines[4].split()))
    p0 = [x - 1 for x in p]

    @lru_cache(maxsize=100000)
    def dp(step, tup):
        if step == u:
            score = 0
            for i in range(n):
                score += tup[i] ^ b[i] ^ k[i]
            return score

        arr = list(tup)
        op1 = tuple([arr[i] ^ arr[p0[i]] for i in range(n)])
        op2 = tuple([arr[i] ^ r for i in range(n)])

        return max(dp(step + 1, op1), dp(step + 1, op2))

    return str(dp(0, tuple(a)))

