MOD = 10**9 + 7

def mat_mul(A, B):
    """Multiply two 3x3 matrices modulo MOD"""
    C = [[0] * 3 for _ in range(3)]
    for i in range(3):
        for j in range(3):
            for k in range(3):
                C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % MOD
    return C

def mat_pow(A, p):
    """Compute A^p modulo MOD using binary exponentiation"""
    res = [[0] * 3 for _ in range(3)]
    for i in range(3):
        res[i][i] = 1
    while p > 0:
        if p % 2 == 1:
            res = mat_mul(res, A)
        A = mat_mul(A, A)
        p //= 2
    return res

def power(a, b, mod):
    """Compute a^b mod mod using binary exponentiation"""
    res = 1
    a %= mod
    while b > 0:
        if b % 2 == 1:
            res = res * a % mod
        a = a * a % mod
        b //= 2
    return res

