from collections import deque

def solution(data):
    lines = data.strip().split('\n')
    n, m = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))

    good_pairs = []
    for i in range(2, 2 + m):
        u, v = map(int, lines[i].split())
        good_pairs.append((u-1, v-1))  # Convert to 0-indexed

    # Collect all unique prime factors
    all_factors = set()
    for x in a:
        temp = x
        d = 2
        while d * d <= temp:
            if temp % d == 0:
                all_factors.add(d)
                while temp % d == 0:
                    temp //= d
            d += 1
        if temp > 1:
            all_factors.add(temp)

    def get_exponent(num, p):
        count = 0
        while num > 0 and num % p == 0:
            count += 1
            num //= p
        return count

    # Dinic's max flow algorithm
    class Dinic:
        def __init__(self, n_node):
            self.n = n_node
            self.graph = [[] for _ in range(n_node)]
            self.level = []

        def add_edge(self, u, v, capacity):
            self.graph[u].append([v, len(self.graph[v]), capacity])
            self.graph[v].append([u, len(self.graph[u]) - 1, 0])

        def bfs(self, s, t):
            self.level = [-1] * self.n
            self.level[s] = 0
            queue = deque([s])
            while queue:
                u = queue.popleft()
                for v, rev, cap in self.graph[u]:
                    if cap > 0 and self.level[v] < 0:
                        self.level[v] = self.level[u] + 1
                        queue.append(v)
            return self.level[t] >= 0

        def dfs(self, u, t, flow, ptr):
            if u == t or flow == 0:
                return flow
            for i in range(ptr[u], len(self.graph[u])):
                ptr[u] = i
                v, rev, cap = self.graph[u][i]
                if self.level[v] == self.level[u] + 1 and cap > 0:
                    pushed = self.dfs(v, t, min(flow, cap), ptr)
                    if pushed > 0:
                        self.graph[u][i][2] -= pushed
                        self.graph[v][rev][2] += pushed
                        return pushed
            return 0

        def max_flow(self, s, t):
            max_f = 0
            while self.bfs(s, t):
                ptr = [0] * self.n
                while True:
                    pushed = self.dfs(s, t, float('inf'), ptr)
                    if pushed == 0:
                        break
                    max_f += pushed
            return max_f

    total_operations = 0

    for p in all_factors:
        exponents = [get_exponent(x, p) for x in a]

        # Odd positions (in 0-based: 1, 3, 5...)
        # Even positions (in 0-based: 0, 2, 4...)

        # Node mapping
        source = 2 * n + 1
        sink = 2 * n + 2
        node_map = list(range(n)) + [source, sink]

        dinic = Dinic(2*n + 3)

        # Connect source to odd indices
        for i in range(n):
            if i % 2 == 1:  # odd index
                dinic.add_edge(source, node_map[i], exponents[i])
        # Connect even indices to sink
        for i in range(n):
            if i % 2 == 0:  # even index
                dinic.add_edge(node_map[i], sink, exponents[i])

        # Add good pair edges
        for u, v in good_pairs:
            # Ensure proper direction (even -> odd)
            if u % 2 == 0 and v % 2 == 1:
                dinic.add_edge(node_map[u], node_map[v], float('inf'))
            elif v % 2 == 0 and u % 2 == 1:
                dinic.add_edge(node_map[v], node_map[u], float('inf'))

        total_operations += dinic.max_flow(source, sink)

    return f"{total_operations}\n"

