from collections import defaultdict

def solution(input_str):
    if not input_str.strip():
        return ""

    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    # If all edges are in the MST, nothing to output
    if m == n - 1:
        return ""

    edges = []
    for i in range(1, m + 1):
        a, b, e = map(int, lines[i].split())
        # Store edge with its original index
        edges.append((a - 1, b - 1, e, i))  # 0-indexed vertices

    # Union-Find for Kruskal's algorithm
    parent = list(range(n))
    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        px, py = find(x), find(y)
        if px != py:
            parent[px] = py
            return True
        return False

    # Sort edges by weight for MST
    edges_sorted = sorted(edges, key=lambda x: x[2])

    # Build MST using Kruskal's algorithm
    mst_adj = defaultdict(list)
    is_tree_edge = [False] * m  # Track which edges are in MST

    for u, v, w, idx in edges_sorted:
        if union(u, v):
            mst_adj[u].append((v, w))
            mst_adj[v].append((u, w))
            is_tree_edge[idx] = True

    # Build DFS to compute depths and parents for each node
    depth = [-1] * n
    parent_node = [-1] * n

    # Start DFS from node 0
    stack = [(0, -1, 0)]  # (node, parent, weight_to_parent)

    while stack:
        u, p, w = stack.pop()
        depth[u] = depth[p] + 1 if p != -1 else 0
        parent_node[u] = p

        for v, weight in mst_adj[u]:
            if depth[v] == -1:
                stack.append((v, u, weight))

    # Binary lifting preprocessing (LCA and max weight on path)
    LOG = 20  # 2^20 > 10^5 nodes
    up = [[-1] * LOG for _ in range(n)]
    max_w = [[0] * LOG for _ in range(n)]

    # Initialize 2^0 (direct parent pointers)
    for i in range(n):
        if i > 0:  # All nodes except root are processed in DFS
            up[i][0] = parent_node[i]
            max_w[i][0] = max(mst_adj[i][0][1] for v, w in mst_adj[i] if v == parent_node[i] if parent_node[i] != -1 else u for v, w in mst_adj[i])

    # Build sparse table
    for j in range(1, LOG):
        for i in range(n):
            if up[i][j-1] != -1:
                up[i][j] = up[up[i][j-1]][j-1] if up[up[i][j-1]][j-1] != -1 else -1
                if up[i][j-1] != -1:
                    prev_max = max_w[i][0]
                    ancestor_max = max_w[up[i][j-1]][j-1]
                    max_w[i][j] = prev_max if ancestor_max <= prev_max else ancestor_max

    # For proper understanding, let's track max_w at each level directly
    for j in range(1, LOG):
        for i in range(n):
            if up[i][j-1] != -1:
                up[i][j] = up[up[i][j-1]][j-1]
                max_w[i][j] = max(max_w[i][j-1], max_w[up[i][j-1]][j-1]) if up[i][j] != -1 else max_w[i][j-1]
            else:
                up[i][j] = -1
                max_w[i][j] = max_w[i][j-1]

    # LCA function
    def get_lca(u, v):
        if depth[u] < depth[v]:
            u, v = v, u

        # Bring u to same depth as v
        diff = depth[u] - depth[v]
        for j in range(LOG):
            if (diff >> j) & 1:
                u = up[u][j]

        if u == v:
            return u

        # Lift both u and v
        for j in range(LOG-1, -1, -1):
            if up[u][j] != up[v][j]:
                u = up[u][j]
                v = up[v][j]

        return up[u][0]

    # Max weight on path function
    def max_on_path(u, v):
        if u == v:
            return 0

        lca = get_lca(u, v)

        # Find max on path u -> lca
        max_u = 0
        temp = u
        rem = depth[temp] - depth[lca]
        for j in range(LOG):
            if (rem >> j) & 1:
                max_u = max(max_u, max_w[temp][j])
                temp = up[temp][j]

        # Find max on path v -> lca
        max_v = 0
        temp = v
        rem = depth[temp] - depth[lca]
        for j in range(LOG):
            if (rem >> j) & 1:
                max_v = max(max_v, max_w[temp][j])
                temp = up[temp][j]

        return max(max_u, max_v)

    # Process non-MST edges in input order
    results = []
    for i in range(m):
        u, v, w, idx = edges[i]
        if not is_tree_edge[idx]:
            mex_w = max_on_path(u, v)
            results.append(str(mex_w))

    return '\n'.join(results) if results else ""

