sys.setrecursionlimit(500000)

def solution(input_data):
    lines = input_data.strip().split('\n')
    n, m, k = map(int, lines[0].split())

    adj = [[] for _ in range(n + 1)]
    for i in range(1, m + 1):
        v, u = map(int, lines[i].split())
        adj[v].append(u)
        adj[u].append(v)

    # First, try to find cycles (Solving's solution)
    cycles = []
    used_in_cycles = [False] * (n + 1)

    def find_cycle_from(start):
        """Find a cycle from start vertex using DFS"""
        path = [start]
        parent = {}
        parent[start] = -1
        visited = {start}

        stack = [start]

        while stack:
            u = stack[-1]
            for v in adj[u]:
                if v == start and len(path) >= 3:
                    # Found cycle back to start
                    if len(path) % 3 != 0:
                        return path[:-1]
                elif v not in visited:
                    visited.add(v)
                    parent[v] = u
                    path.append(v)
                    stack.append(v)
                else:
                    # Back edge to ancestor
                    if v in parent and v != start:
                        # Found cycle from v to u
                        idx = path.index(v)
                        cycle = path[idx:]
                        if len(cycle) >= 3 and len(cycle) % 3 != 0:
                            return cycle
            stack.pop()

        return None

    # Try to find k cycles
    def find_k_cycles():
        for start in range(1, n + 1):
            if len(cycles) >= k:
                break
            if used_in_cycles[start]:
                continue

            cycle = find_cycle_from(start)
            if cycle:
                # Check if cycle is valid (not using any used vertex as non-rep)
                valid = True
                for v in cycle:
                    if used_in_cycles[v]:
                        valid = False
                        break
                    if len(cycles) >= k:
                        break
                if valid:
                    cycles.append(cycle)
                    # Mark all vertices except first as used
                    for v in cycle[1:]:
                        used_in_cycles[v] = True
                    # First vertex is the representative, keep it available
                    used_in_cycles[start] = False

        return len(cycles) >= k

    if find_k_cycles():
        result = ["CYCLES"]
        for i in range(k):
            cycle = cycles[i]
            result.append(str(len(cycle) + 1))
            result.append(" ".join(map(str, cycle + [cycle[0]])))
        return "\n".join(result)

    # If cycles don't work, try to find a long path (Johnny's solution)
    best_path = []
    best_len = 0

    def dfs_path(u, path, visited):
        nonlocal best_path, best_len

        if len(path) > best_len:
            best_len = len(path)
            best_path = path.copy()

        for v in adj[u]:
            if v not in visited:
                visited.add(v)
                dfs_path(v, path + [v], visited)
                visited.remove(v)

    for start in range(1, n + 1):
        if best_len >= n // k:
            break
        dfs_path(start, [start], {start})
        if best_len >= n // k:
            break

    if best_len >= n // k:
        result = ["PATH"]
        result.append(str(best_len))
        result.append(" ".join(map(str, best_path)))
        return "\n".join(result)

    return "-1"


