    # Directions: right, left, down, up
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]

    def can_dominate(S_set):
        """Check if every cell can move to a cell in S (stay or move adjacent)"""
        for i in range(n):
            for j in range(m):
                if (i, j) in S_set:
                    continue
                # Is there a direction pointing from (i,j) to S_set?
                found_target = False
                for dr, dc in directions:
                    ni, nj = i + dr, j + dc
                    if 0 <= ni < n and 0 <= nj < m and (ni, nj) in S_set:
                        found_target = True
                        break
                if not found_target:
                    return False
        return True

    # Try all possible dominating set sizes from 1 to total - 1
    for size in range(1, total - 1 + 1):
        for subset in itertools.combinations(cells, size):
            subset_set = set(subset)
            if can_dominate(subset_set):
                return str(total - size)

    # Fallback for edge cases (shouldn't reach here for n*m >= 2)
    if total == 1:
        return '0'

    return '0'

class UnionFind:
    def __init__(self, n):
        self.parent = list(range(n + 1))
        self.xor_val = [0] * (n + 1)

    def find(self, i):
        if self.parent[i] != i:
            root = self.find(self.parent[i])
            self.xor_val[i] ^= self.xor_val[self.parent[i]]
        return self.parent[i]

    def union(self, i1, i2, target_xor):
        root1 = self.find(i1)
        root2 = self.find(i2)

        if root1 == root2:
            current_xor = self.xor_val[i1] ^ self.xor_val[i2]
            if current_xor != target_xor:
                return False  # Contradiction detected
            return True
        else:
            self.parent[root1] = root2
            self.xor_val[root1] = self.xor_val[i1] ^ self.xor_val[i2] ^ target_xor
            return True

    def count_components(self):
        count = 0
        for i in range(1, len(self.parent)):
            if self.parent[i] == i:
                count += 1
        return count

