        for p in primes:
            if a[i] % p == 0:
                prime_coverers[i].append(p)

    # DP: dp[mask] = min experience to eliminate primes in mask
    # mask: bitmask representing which primes are already eliminated

    dp = [float('inf')] * (1 << m)
    dp[0] = 0

    for mask in range(1 << m):
        if dp[mask] == float('inf'):
            continue

        for i in range(n):
            # Try playing with judge i
            new_mask = mask
            new_exp = dp[mask] + e[i]

            for p_idx in range(m):
                if p_idx in prime_coverers[i]:
                    new_mask |= (1 << p_idx)

            if new_exp < dp[new_mask]:
