import heapq

def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    x = list(map(int, lines[1].split()))
    a, b = map(int, lines[2].split())

    if a == b:
        return '0'

    # Use unique sorted x values for optimization
    x = sorted(list(set(x)))

    # dist[i] = minimum moves to get from position a to position b + i
    # We want dist[0] (position b)
    MAX_POS = a - b

    dist = [float('inf')] * (MAX_POS + 1)
    dist[MAX_POS] = 0
    heap = [(0, MAX_POS)]  # (distance, position_index)

    while heap:
        d, u = heapq.heappop(heap)

        if u == 0:
            return str(d)

        if d > dist[u]:
            continue

        current_pos = b + u

        # Move 1: subtract 1
        if u > 0 and dist[u - 1] > d + 1:
            dist[u - 1] = d + 1
            heapq.heappush(heap, (d + 1, u - 1))

        # Move 2: use xi to subtract (current_pos % xi)
        for xi in x:
            # Optimization: if xi > current_pos, we jump directly to b
            if xi > current_pos:
                if dist[0] > d + 1:
                    dist[0] = d + 1
                    heapq.heappush(heap, (d + 1, 0))
                break  # All larger xi values also jump directly to b

            target = current_pos - (current_pos % xi)
            if target >= b:
                v = target - b
                if dist[v] > d + 1:
                    dist[v] = d + 1
                    heapq.heappush(heap, (d + 1, v))

    return str(dist[0])

