    if n == m:
        # Check if elements are consecutive integers from 0 to m-1
        if a == list(range(m)):
            return "0 1\n"
        # Try each possible difference for complete residue system
        for d in range(1, m):
            elements = {}
            for i in range(n):
                elements[(0 + i * d) % m] = i
            # Check if all n elements are present
            if len(elements) == n:
                return f"0 {d}\n"
        return "-1\n"

    # Compute differences between consecutive sorted elements
    diffs = []
    for i in range(n - 1):
        diffs.append((a[i+1] - a[i]) % m)
    # Wraparound difference
    wrap = (a[0] - a[n-1]) % m
    diffs.append(wrap)

