def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())
    edges = []
    for i in range(m):
        u, v = map(int, lines[1 + i].split())
        edges.append((u, v))

    # Build conflict graph - edges that cross must have different positions
    adj = [[] for _ in range(m)]
    for i in range(m):
        u1, v1 = edges[i]
        if u1 > v1:
            u1, v1 = v1, u1
        for j in range(i + 1, m):
            u2, v2 = edges[j]
            if u2 > v2:
                u2, v2 = v2, u2

            # Check if exactly one endpoint of edge j is strictly between u1 and v1
            in_r1 = u2 > u1 and u2 < v1
            in_r2 = v2 > u1 and v2 < v1

            if in_r1 != in_r2:
                adj[i].append(j)
                adj[j].append(i)

    # 2-color the conflict graph (bipartite check)
    colors = {}
    for i in range(m):
        if i not in colors:
            colors[i] = 0
            q = deque([i])
            while q:
                curr = q.popleft()
                for neighbor in adj[curr]:
                    if neighbor not in colors:
                        colors[neighbor] = 1 - colors[curr]
                        q.append(neighbor)
                    elif colors[neighbor] == colors[curr]:
                        return "Impossible"

    # Convert to output string (0 -> inside 'i', 1 -> outside 'o')
    ans = ''.join('i' if colors[i] == 0 else 'o' for i in range(m))
    return ans


