import bisect

def solution(input_str):
    lines = input_str.strip().split('\n')

    n, m = map(int, lines[0].split())
    k = list(map(int, lines[1].split()))

    # offers[t] contains all days when type t is on sale
    offers = [[] for _ in range(n + 1)]
    for i in range(2, 2 + m):
        d, t = map(int, lines[i].split())
        offers[t].append(d)

    # Sort each list for binary search
    for i in range(1, n + 1):
        offers[i].sort()

    def can_buy(day):
        """Check if all items can be bought by day D"""
        cost = 0
        for i in range(n):
            if k[i] > 0:
                # Find the latest sale day for type (i+1) that is <= day
                sale_day = -1
                if offers[i + 1]:
                    idx = bisect.bisect_right(offers[i + 1], day) - 1
                    if idx >= 0:
                        sale_day = offers[i + 1][idx]

                if sale_day != -1:
                    cost += k[i]  # Buy at sale price: 1 burle per item
                else:
                    cost += k[i] * 2  # Buy at normal price: 2 burles per item

        return cost <= day

    # Binary search for minimum day
    left, right = 1, 400000
    ans = right

    while left <= right:
        mid = (left + right) // 2
        if can_buy(mid):
            ans = mid
            right = mid - 1
        else:
            left = mid + 1

    return str(ans) + '\n'

def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    a = list(map(int, lines[1].split()))

    MOD = 10**9 + 7

    current = list(a)
    row_num = 0

    while len(current) > 1:
        row_num += 1
        next_row = []

        # Determine if this row starts with addition
        # Row 1 starts with addition (row_num is 1, odd)
        # Each subsequent row flips relative to previous
        start_add = (row_num % 2 == 1)

        for i in range(len(current) - 1):
            if start_add:
                # Pattern: +, -, +, -, ... when starting with add
                if i % 2 == 0:
                    val = (current[i] + current[i+1]) % MOD
                else:
                    val = (current[i+1] - current[i]) % MOD
            else:
                # Pattern: -, +, -, +, ... when starting with sub
                if i % 2 == 0:
                    val = (current[i] - current[i+1]) % MOD
                else:
                    val = (current[i+1] - current[i]) % MOD
            next_row.append(val)

        current = next_row

    result = current[0] % MOD
    if result < 0:
        result += MOD
    return str(result)

def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return "-1"

    n = int(lines[0])
    x1, y1, x2, y2 = map(float, lines[1].split())

    max_start = -float('inf')
    min_end = float('inf')

    for i in range(2, 2 + n):
        parts = lines[i].split()
        rix, riy, vix, viy = map(float, parts)

        for pos, vel, b1, b2 in [(rix, vix, x1, x2), (riy, viy, y1, y2)]:
            if vel == 0:
                # Must be already strictly inside
                if not (b1 < pos < b2):
                    return "-1"
                continue

            if vel > 0:
                if pos < b1:
                    # Will enter from left
                    start = (b1 - pos) / vel
                    end = (b2 - pos) / vel
                else:  # pos >= b1 (already inside at t=0)
                    start = 0.0
                    end = (b2 - pos) / vel
            else:  # vel < 0
                if pos > b2:
                    # Will enter from right
                    start = (pos - b2) / vel  # negative positive / neg = positive
                    end = float('inf')
                else:  # pos <= b2 (already inside at t=0 or at boundary moving outward - invalid)
                    if pos < b2:
                        start = 0.0
                        end = (pos - b1) / vel
                    else:  # pos == b2 (exactly on boundary, not strictly inside)
                        return "-1"

            if start < 0:
                start = 0.0

            max_start = max(max_start, start)
            min_end = min(min_end, end)

    if max_start >= min_end or max_start == -float('inf'):
        return "-1"

    return str(max_start)

