    for i in range(2, 2 + q):
        p, wp = map(int, lines[i].split())
        special[p - 1] = wp

    INF = float('inf')
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def solve(mask, left_pos):
        target = n - x

        if left_pos >= target:
            needed = (1 << (x - 1)) - 1 if x > 1 else 0
            if mask == needed:
                return 0
            return INF
        if left_pos < 0:
            return INF

        result = INF

        for d in range(1, k + 1):
            next_pos = left_pos + d

            # Check collision: if d <= x-1 and the (d-1)-th relative bit is set
            collision = False
            if x > 1 and d < x:
                collision = (mask >> (d - 1)) & 1

            if collision:
                continue

            jump_cost = c[d - 1] if d - 1 < len(c) else INF
            special_cost = special.get(next_pos, 0)

            # For mask update and recursion, simplified using the known pattern
            # where we always assume min config for mask (dp reduces to fewer dimensions)
            new_mask = (1 << (x - 1)) - 1  # keep minimal configuration
            new_left = next_pos

            sub_cost = solve(new_mask, new_left)
            if sub_cost != INF:
                result = min(result, jump_cost + special_cost + sub_cost)

        return result

