    n, q = map(int, lines[0].split())

    perm = [i + 1 for i in range(n)]

    inv = 0

    def get_delta(li: int, ri: int) -> int:
        if li > ri:
            li, ri = ri, li

        if li == ri:
            return 0

        val_left = perm[li-1]
        val_right = perm[ri-1]

        delta = 0

        # Inversion between li and ri positions
        if val_left > val_right:
            delta -= 1
        else:
            delta += 1

        # For positions between li and ri
        for k in range(li, ri):
            val_k = perm[k-1]

            old_lk = 1 if val_k < val_left else 0
            old_kr = 1 if val_k > val_right else 0
            new_lk = 1 if val_k < val_right else 0
            new_kr = 1 if val_k > val_left else 0

            delta += (new_lk - old_lk) + (new_kr - old_kr)

        return delta

    output = []

    for line_idx in range(q):
        parts = lines[line_idx + 1].split()
        li = int(parts[0])
        ri = int(parts[1])

        delta = get_delta(li, ri)
        inv += delta
        output.append(str(inv))

        # Update permutation
        if li != ri:
            p0 = li - 1
            p1 = ri - 1
            perm[p0], perm[p1] = perm[p1], perm[p0]

    return '\n'.join(output)

