def get_canonical(s):
    """Get the canonical form of a string s"""
    def flip(x):
        return ''.join('1' if c == '0' else '0' for c in x)

    # Consider all 4 transformations
    transformations = [s, s[::-1], flip(s), flip(s[::-1])]
    return min(transformations)

