def solution(input_str):
    parts = input_str.strip().split('\n')[0].split()
    n, m = int(parts[0]), int(parts[1])

    # Define the 4 T-shape patterns with 5 cells each
    # Pattern 1: T pointing up (### above)
    # ###\n.#.\n.#.
    pattern1 = [(0, 0), (0, 1), (0, 2), (1, 1), (2, 1)]

    # Pattern 2: T pointing down (### below)
    # ..#\n###\n..#
    pattern2 = [(0, 2), (1, 0), (1, 1), (1, 2), (2, 2)]

    # Pattern 3: T pointing left (### on right)
    # .#.\n..#\n###
    pattern3 = [(0, 1), (1, 2), (2, 0), (2, 1), (2, 2)]

    # Pattern 4: T pointing right (### on left)
    # #..\n###\n#..
    pattern4 = [(0, 0), (0, 1), (0, 2), (1, 0), (2, 0)]

    patterns = [pattern1, pattern2, pattern3, pattern4]

    grid = [['.' for _ in range(m)] for _ in range(n)]
    occupied = [[False for _ in range(m)] for _ in range(n)]

    best_count = [0]
    best_grid = [None]

    # Upper bound optimization: kind of ceil(n*m/5)
    max_possible = (n * m + 4) // 5

    def can_place(pattern, r, c):
        for dr, dc in pattern:
            nr, nc = r + dr, c + dc
            if not (0 <= nr < n and 0 <= nc < m):
                return False
            if occupied[nr][nc]:
                return False
        return True

    def place_pattern(pattern, r, c, shape_idx):
        for dr, dc in pattern:
            nr, nc = r + dr, c + dc
            grid[nr][nc] = chr(ord('A') + shape_idx)
            occupied[nr][nc] = True

    def remove_pattern(pattern, r, c):
        for dr, dc in pattern:
            nr, nc = r + dr, c + dc
            grid[nr][nc] = '.'
            occupied[nr][nc] = False

    def backtrack(count, letter_idx):
        global best_count, best_grid

        # Update best solution
        if count > best_count[0]:
            best_count[0] = count
            best_grid = [row[:] for row in grid[:]] if grid else None

        # Branching: if any free cell, continue placing
        placed_trivial = False
        for r in range(n):
            for c in range(m):
                if not occupied[r][c]:
                    for p_idx, pattern in enumerate(patterns):
                        if can_place(pattern, r, c):
                            place_pattern(pattern, r, c, count)
                            backtrack(count + 1, count)
                            remove_pattern(pattern, r, c)
                    placed_trivial = True

        # Early termination optimization: if count + remaining_unfit_leaves best
        # Actually let's compute remaining free cells
        frees = sum(1 for r in range(n) for c in range(m) if not occupied[r][c])
        # Each turboplow needs 5 cells
        if count + frees // 5 <= best_count[0]:
            return

        # If no more placements possible, still check if this is best
        if count > best_count[0]:
            best_count[0] = count
            best_grid = [row[:] for row in grid[:]] if grid else None

        # Early exit if we already found max possible
        if count == max_possible:
            return

        # Try to place at least some more (DFS style)
        for r in range(n):
            for c in range(m):
                if not occupied[r][c]:
                    for p_idx, pattern in enumerate(patterns):
                        if can_place(pattern, r, c):
                            place_pattern(pattern, r, c, count)
                            backtrack(count + 1, count)
                            remove_pattern(pattern, r, c)
                    break  # Just one try per cell

    # Actually better approach: DFS order
    def solve():
        # Try placing shapes
        for start_r in range(n):
            for start_c in range(m):
                for p_idx, pattern in enumerate(patterns):
                    if can_place(pattern, start_r, start_c):
                        place_pattern(pattern, start_r, start_c, 0)
                        backtrack(1, 0)
                        remove_pattern(pattern, start_r, start_c)

    solve()

    # Format result
    result_lines = []
    result_lines.append(str(best_count[0]))
    for row in best_grid:
        result_lines.append(''.join(row))

    return '\n'.join(result_lines) + '\n'

