def get_points(r):
    """Get all integer points within distance r from origin"""
    points = []
    for x in range(-r, r + 1):
        for y in range(-r, r + 1):
            if x * x + y * y <= r * r:
                points.append((x, y))
    return points

def sum_sq_pairwise(points):
    """Calculate sum of squared distances between all pairs"""
    n = len(points)
    total = 0
    for i in range(n):
        for j in range(i + 1, n):
            dx = points[i][0] - points[j][0]
            dy = points[i][1] - points[j][1]
            total += dx * dx + dy * dy
    return total

def solve(n, r):
    points = get_points(r)
    best_sum = -1
    best_config = None

    # Use backtracking to find optimal configuration
    best_sum = -1
    best_config = None

    def backtrack(start, current):
        nonlocal best_sum, best_config

        if len(current) == n:
            s = sum_sq_pairwise(current)
            if s > best_sum:
                best_sum = s
                best_config = list(current)
            return

        if start >= len(points):
            return
        if len(current) + (len(points) - start) < n:
            return

        for i in range(start, len(points)):
            current.append(points[i])
            backtrack(i + 1, current)
            current.pop()

    backtrack(0, [])

    # Format output
    result = str(best_sum) + '\n'
    for p in best_config:
        result += f"{p[0]} {p[1]}\n"
    return result

def solution(input_str):
    n, r = map(int, input_str.strip().split())
    return solve(n, r)
